export const W=1000,H=760;
export const nodes=Array.from({length:63},(_,i)=>({id:i,x:100+i%9*100,y:80+Math.floor(i/9)*100}));
export const places=[['성수역',55],['서울숲 입구',8],['연무장길',30],['성수 아틀리에',14],['뚝섬역',1],['숲길 카페',44]];
// Synthetic city blocks, coordinates and heights: not real Seoul survey data.
export const buildings=[];
for(let y=0;y<6;y++)for(let x=0;x<8;x++){if(x>5&&y<2)continue;buildings.push({x:118+x*100,y:98+y*100,w:34+(x*7+y*3)%35,h:40+(x*3+y*7)%28,height:10+(x*13+y*17)%65});}
export const edges=nodes.flatMap(n=>[n.id%9<8?n.id+1:null,n.id<54?n.id+9:null].filter(v=>v!==null).map(v=>({a:n.id,b:v,length:100,walkOnly:n.id%9>=6&&n.id>=9&&n.id<18&&v===n.id+1})));
export function sun(date,minutes){const day=Math.floor((Date.parse(date+'T12:00:00Z')-Date.parse(date.slice(0,4)+'-01-01T12:00:00Z'))/86400000)+1;const d=Math.PI/180,decl=23.44*d*Math.sin(2*Math.PI*(284+day)/365),lat=37.54*d,ha=(minutes/60-12.53)*15*d;const east=-Math.cos(decl)*Math.sin(ha),north=Math.cos(lat)*Math.sin(decl)-Math.sin(lat)*Math.cos(decl)*Math.cos(ha),up=Math.sin(lat)*Math.sin(decl)+Math.cos(lat)*Math.cos(decl)*Math.cos(ha);return {east,north,up,altitude:Math.asin(up)/d};}
function hull(points){const p=points.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);const cross=(o,a,b)=>(a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0]);let lo=[],hi=[];for(const q of p){while(lo.length>1&&cross(lo.at(-2),lo.at(-1),q)<=0)lo.pop();lo.push(q);}for(const q of [...p].reverse()){while(hi.length>1&&cross(hi.at(-2),hi.at(-1),q)<=0)hi.pop();hi.push(q);}return lo.slice(0,-1).concat(hi.slice(0,-1));}
export function shadows(date,minutes){const s=sun(date,minutes);if(s.up<=0)return [];return buildings.map(b=>{const scale=b.height/Math.max(.035,s.up),dx=-s.east*scale,dy=s.north*scale;const p=[[b.x,b.y],[b.x+b.w,b.y],[b.x+b.w,b.y+b.h],[b.x,b.y+b.h]];return hull(p.concat(p.map(([x,y])=>[x+dx,y+dy])));});}
function inside(x,y,p){let c=false;for(let i=0,j=p.length-1;i<p.length;j=i++){const a=p[i],b=p[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])c=!c;}return c;}
export function shadeAt(x,y,date,time,polys){if(sun(date,time).up<=0)return 1;return (polys||shadows(date,time)).some(p=>inside(x,y,p))?1:0;}
export function route({start,end,date,time,mode='walk',kind='balanced'}){const speed=mode==='bike'?250:75,weight={fast:0,balanced:1.2,shade:5}[kind];const costs=nodes.map(()=>Infinity),arrival=nodes.map(()=>0),previous=[],done=new Set(),metrics=[];costs[start]=0;while(done.size<nodes.length){let u=-1;for(const n of nodes)if(!done.has(n.id)&&(u<0||costs[n.id]<costs[u]))u=n.id;if(u<0||!Number.isFinite(costs[u])||u===end)break;done.add(u);for(const e of edges){if(mode==='bike'&&e.walkOnly)continue;let v=e.a===u?e.b:e.b===u?e.a:-1;if(v<0||done.has(v))continue;let shaded=0;const duration=e.length/speed;for(let k=0;k<5;k++){const t=(k+.5)/5,at=time+arrival[u]+duration*t;shaded+=shadeAt(nodes[u].x+(nodes[v].x-nodes[u].x)*t,nodes[u].y+(nodes[v].y-nodes[u].y)*t,date,at)/5;}const cost=costs[u]+duration*(1+weight*(1-shaded));if(cost<costs[v]){costs[v]=cost;arrival[v]=arrival[u]+duration;previous[v]=u;metrics[v]={length:e.length,shaded};}}}if(!Number.isFinite(costs[end]))return null;let path=[end],length=0,shadeLength=0;while(path[0]!==start){const v=path[0],m=metrics[v];length+=m.length;shadeLength+=m.length*m.shaded;path.unshift(previous[v]);}return {kind,path,length,minutes:length/speed,shade:length?shadeLength/length:0,sunMinutes:(length-shadeLength)/speed};}
